'AC-runtime.6.1'; from __future__ import annotations; from pathlib import Path; from unittest.mock import AsyncMock; import pytest; from httpx import AsyncClient; from src.boot import Bootloader, ServiceStatus; from src.runtime import DEPENDENCY_MANIFEST, EnvTier; _ALL_OK = {'_check_s3': ServiceStatus('minio', 'ok', 'OK'), '_check_openrouter': ServiceStatus('ai_provider', 'ok', 'OK'), '_check_cache': ServiceStatus('cache', 'ok', 'OK'), '_check_workflow_engine': ServiceStatus('workflow_engine', 'ok', 'OK'), '_check_telemetry': ServiceStatus('telemetry', 'ok', 'OK'), '_check_analytics': ServiceStatus('analytics', 'ok', 'OK'), '_check_market_data': ServiceStatus('market_data', 'ok', 'OK')}
class _DummyAsyncSession:
    async def execute(self, *args, **kwargs): return None
class _DummyAsyncSessionContext:
    async def __aenter__(self): return _DummyAsyncSession()
    async def __aexit__(self, exc_type, exc_val, exc_tb): pass
_dummy_session_maker = lambda: _DummyAsyncSessionContext()
def _stub_probes(monkeypatch, **overrides: ServiceStatus) -> None: import src.runtime.extension.api.health as health_api; monkeypatch.setattr(health_api, '_test_session_maker', _dummy_session_maker); [monkeypatch.setattr(Bootloader, method, AsyncMock(return_value=status)) for method, status in {**_ALL_OK, **overrides}.items()]
async def test_AC_runtime_6_1_full_health_asserts_the_declared_set(client: AsyncClient, monkeypatch) -> None: 'AC-runtime.6.1'; _stub_probes(monkeypatch); response = await client.get('/health?full=1'); assert response.status_code == 200; body = response.json(); tier = EnvTier(body['tier']); declared = DEPENDENCY_MANIFEST.required_for(tier); reported = set(body['checks']) - {'s3'} | ({'object_storage'} if 's3' in body['checks'] else set()); assert reported == declared, f'declared {sorted(declared)} vs reported {sorted(reported)}'
async def test_full_health_503_when_a_declared_dep_is_absent(client: AsyncClient, monkeypatch) -> None: _stub_probes(monkeypatch, _check_s3=ServiceStatus('minio', 'error', 'down')); response = await client.get('/health?full=1'); assert response.status_code == 503; assert response.json()['status'] == 'unhealthy'
async def test_plain_health_stays_light(client: AsyncClient, monkeypatch) -> None: _stub_probes(monkeypatch); response = await client.get('/health'); assert response.status_code == 200; body = response.json(); assert body['checks'] == {'liveness': True}; assert 'tier' not in body
async def test_health_reports_the_sdk_environment_tier_as_a_second_opinion(client: AsyncClient, monkeypatch) -> None: import os; from infra2_sdk.runtime.environment import resolve_environment_tier; from src.config import settings; _stub_probes(monkeypatch); response = await client.get('/health'); assert response.status_code == 200; body = response.json(); expected = resolve_environment_tier(settings.environment, github_actions=os.getenv('GITHUB_ACTIONS', '').lower() == 'true', unknown='production'); assert body['sdk_environment_tier'] == expected.value
def test_smoke_script_calls_the_full_health_form() -> None: script = Path(__file__).resolve().parents[4] / 'common/runtime/shell/smoke_test.sh'; content = script.read_text(encoding='utf-8'); assert 'api/health?full=1' in content, 'smoke_test.sh no longer asserts the manifest-declared dependency set'
@pytest.mark.no_db
@pytest.mark.parametrize('tier', list(EnvTier))
def test_every_tier_declaration_is_smoke_assertable(tier: EnvTier) -> None: probed, unprobed = Bootloader._required_checks(tier); assert set(probed) == DEPENDENCY_MANIFEST.required_for(tier); assert unprobed == []
_LIVENESS_BODY_KEYS = {'status', 'timestamp', 'version', 'git_sha', 'checks', 'observability', 'sdk_environment_tier'}
@pytest.mark.parametrize(('path', 'expected_keys'), [('/health', _LIVENESS_BODY_KEYS), ('/health?full=1', _LIVENESS_BODY_KEYS | {'tier'})])
async def test_health_body_carries_only_the_pinned_fields(client: AsyncClient, monkeypatch, path: str, expected_keys: set[str]) -> None: _stub_probes(monkeypatch); response = await client.get(path); assert response.status_code == 200; assert set(response.json()) == expected_keys
async def test_health_unexpected_failure_logs_error_id(client: AsyncClient, monkeypatch) -> None: from unittest.mock import AsyncMock, MagicMock; import src.runtime.extension.api.health as health_api; from src.boot import Bootloader; from src.observability import ErrorIds; mock_logger = MagicMock(); monkeypatch.setattr(health_api, 'logger', mock_logger); monkeypatch.setattr(Bootloader, '_check_s3', AsyncMock(side_effect=RuntimeError('catastrophic failure'))); response = await client.get('/health?full=1'); assert response.status_code == 503; assert response.json()['status'] == 'error'; mock_logger.error.assert_called_once(); assert mock_logger.error.call_args.kwargs.get('error_id') == ErrorIds.HEALTH_CHECK_FAILED
async def test_AC_runtime_7_3_plain_health_is_fast_liveness_without_external_io(client: AsyncClient, monkeypatch) -> None: 'AC-runtime.7.3'; from unittest.mock import AsyncMock, MagicMock; import src.runtime.extension.api.health as health_api; from src.boot import Bootloader, ServiceStatus; mock_s3 = AsyncMock(return_value=ServiceStatus('minio', 'ok', 'OK')); monkeypatch.setattr(Bootloader, '_check_s3', mock_s3); mock_db_maker = MagicMock(side_effect=AssertionError('DB session maker invoked on plain liveness')); monkeypatch.setattr(health_api, '_test_session_maker', mock_db_maker); monkeypatch.setattr(health_api, 'async_session_maker', mock_db_maker); response = await client.get('/health'); assert response.status_code == 200; body = response.json(); assert body['status'] == 'healthy'; assert 'timestamp' in body; assert 'git_sha' in body; assert 'checks' in body; assert body['checks'].get('liveness') is True; assert mock_s3.call_count == 0; assert mock_db_maker.call_count == 0; assert 's3' not in body['checks']; assert 'database' not in body['checks']
@pytest.mark.no_db
def test_bootloader_and_health_have_no_vault_secrets_file_coupling() -> None: import src.boot as boot_module; import src.runtime.extension.api.health as health_api; assert not hasattr(Bootloader, '_check_vault_secrets'); assert not hasattr(boot_module, 'VAULT_SECRETS_FILE_PATH'); assert not hasattr(boot_module, 'VAULT_SECRETS_STALENESS_THRESHOLD_SECONDS'); assert not hasattr(health_api, 'VAULT_SECRETS_FILE_PATH')
